#!/usr/bin/env python3
import os
import shutil
import sys

def main():
    # Determine if running as root
    is_root = os.getuid() == 0

    # Check for presence of commands
    has_sudo = shutil.which('sudo') is not None
    has_apt = shutil.which('apt') is not None
    has_apt_get = shutil.which('apt-get') is not None

    cmd = None

    if is_root:
        if has_apt:
            cmd = 'apt'
        elif has_apt_get:
            cmd = 'apt-get'
    else:
        if has_sudo:
            if has_apt:
                cmd = 'sudo apt'
            elif has_apt_get:
                cmd = 'sudo apt-get'

    if cmd:
        print(f"使用 {cmd} …")
    else:
        print("需手动安装或使用其他方式")

if __name__ == "__main__":
    main()
